<script lang="ts">import type {PageProps} from './$types';import {Breadcrumb,Card,Icon,i18n} from '$lib';let {data}:PageProps=$props();const money=(v:string)=>new Intl.NumberFormat(i18n.locale,{style:'currency',currency:'PEN'}).format(Number(v));const cards=$derived([['shopping-cart','operations.totalSales',String(data.ventas)],['circle-dollar-sign','operations.totalIncome',money(data.ingresos)],['wallet-cards','operations.receivable',money(data.por_cobrar)],['calendar-days','nav.appointments',String(data.citas)],['triangle-alert','operations.lowStock',String(data.stock_bajo)],['bell-ring','nav.reminders',String(data.recordatorios)]]);</script>
<Breadcrumb items={[{label:i18n.t('nav.dashboard'),href:'/dashboard'},{label:i18n.t('nav.reports')}]}/><section class="space-y-6"><div><h1 class="text-[28px] font-semibold text-ink">{i18n.t('nav.reports')}</h1><p class="mt-1.5 text-steel">{i18n.t('operations.reportsHelp')}</p></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{#each cards as card}<Card><div class="flex items-center gap-4"><span class="grid size-11 place-items-center rounded-xl bg-primary-soft text-primary"><Icon name={card[0]} size={21}/></span><div><span class="text-sm text-steel">{i18n.t(card[1])}</span><strong class="mt-1 block text-2xl text-ink">{card[2]}</strong></div></div></Card>{/each}</div></section>
